(async () => {
      try {
        const crawlType = trigger?.config.crawl_type as string | undefined;
        console.log(`[Scheduled] Running ${label} (crawl_type: ${crawlType ?? 'full'})`);

        // Banner image health check — daily graveyard shift
        if (crawlType === 'banner-health') {
          const { executeBannerImageHealthCheck } = await import('./sync/crawl-doctor');
          const supabase = createSupabaseClient({ url: env.SUPABASE_URL, serviceRoleKey: env.SUPABASE_SERVICE_ROLE_KEY });
          const result = await executeBannerImageHealthCheck(supabase, env.SLACK_WEBHOOK_URL);

          run.status = 'success';
          run.completedAt = new Date().toISOString();
          run.result = { crawl_type: 'banner-health', ...result };
          await saveRun(bucket, run);
          return;
        }

        // Crawl doctor — resets browser-error pages, deactivates 404s,
        // flags failing OEMs, expires stale offers. Runs before the main
        // crawl window so reset pages get retried the same night.
        if (crawlType === 'crawl-doctor') {
          const { executeCrawlDoctor } = await import('./sync/crawl-doctor');
          const supabase = createSupabaseClient({ url: env.SUPABASE_URL, serviceRoleKey: env.SUPABASE_SERVICE_ROLE_KEY });
          const result = await executeCrawlDoctor(supabase, env.SLACK_WEBHOOK_URL);

          run.status = 'success';
          run.completedAt = new Date().toISOString();
          run.result = { crawl_type: 'crawl-doctor', ...result };
          await saveRun(bucket, run);
          return;
        }

        // Portal asset (DAM) health check — daily, stalest-first rotation.
        // The 800 cap keeps the run inside the Worker's ~1000-subrequest
        // budget; an uncapped run dies mid-check and the R2 record sticks
        // at "running" forever.
        if (crawlType === 'portal-asset-health') {
          const { executePortalAssetHealthCheck } = await import('./sync/crawl-doctor');
          const supabase = createSupabaseClient({ url: env.SUPABASE_URL, serviceRoleKey: env.SUPABASE_SERVICE_ROLE_KEY });
          const result = await executePortalAssetHealthCheck(supabase, env.SLACK_WEBHOOK_URL, { limit: 800 });

          run.status = 'success';
          run.completedAt = new Date().toISOString();
          run.result = { crawl_type: 'portal-asset-health', ...result };
          await saveRun(bucket, run);
          return;
        }

        // Toyota browser sync — uses Apify actor with stealth browser
        if (crawlType === 'toyota-browser-sync') {
          const { runToyotaSyncViaApify } = await import('./sync/toyota-browser-sync');

          if (!env.APIFY_TOKEN) {
            throw new Error('APIFY_TOKEN not configured for Toyota sync');
          }

          const result = await runToyotaSyncViaApify({
            token: env.APIFY_TOKEN,
            supabaseUrl: env.SUPABASE_URL,
            supabaseServiceRoleKey: env.SUPABASE_SERVICE_ROLE_KEY,
            dealerId: env.TOYOTA_DEALER_ID,
          });

          run.status = 'success';
          run.completedAt = new Date().toISOString();
          run.result = { crawl_type: 'toyota-browser-sync', ...result };
          await saveRun(bucket, run);

          if (env.SLACK_WEBHOOK_URL) {
            const notifier = new MultiChannelNotifier({ slackWebhookUrl: env.SLACK_WEBHOOK_URL });
            await notifier.send(
              `🚗 Toyota sync via Apify: ${result.variantsSynced}/${result.variantsDiscovered} variants synced. ` +
              `Errors: ${result.errors.length}`
            ).catch(() => {});
          }
          return;
        }

        // All-OEM specs, colors + pricing sync — same work as the OpenClaw
        // oem-data-sync-daily job, which lost its scheduler when the gateway
        // container stopped running.
        if (crawlType === 'oem-data-sync') {
          const supabase = createSupabaseClient({ url: env.SUPABASE_URL, serviceRoleKey: env.SUPABASE_SERVICE_ROLE_KEY });
          const errors: string[] = [];
          const results: Record<string, unknown> = {};

          try {
            const { executeKiaColorSync } = await import('./sync/kia-colors');
            results.kia_color_sync = await executeKiaColorSync(supabase);
          } catch (e) {
            errors.push(`kia: ${e instanceof Error ? e.message : String(e)}`);
          }

          try {
            const { executeSuzukiSync } = await import('./sync/suzuki-sync');
            results.suzuki_sync = await executeSuzukiSync(supabase);
          } catch (e) {
            errors.push(`suzuki: ${e instanceof Error ? e.message : String(e)}`);
          }

          try {
            const { executeAllOemSync } = await import('./sync/all-oem-sync');
            results.all_oem_sync = await executeAllOemSync(supabase);
          } catch (e) {
            errors.push(`all-oem: ${e instanceof Error ? e.message : String(e)}`);
          }

          run.status = errors.length === 3 ? 'failed' : 'success';
          run.completedAt = new Date().toISOString();
          run.result = { crawl_type: 'oem-data-sync', ...results, errors };
          await saveRun(bucket, run);
          return;
        }

          // Design drift check — special handler
        if (crawlType === 'design-drift') {
          const { TokenCrawler } = await import('./design/token-crawler');
          const crawler = new TokenCrawler({ browser: env.BROWSER! });
          const supabase = createSupabaseClient({ url: env.SUPABASE_URL, serviceRoleKey: env.SUPABASE_SERVICE_ROLE_KEY });
          const notifier = env.SLACK_WEBHOOK_URL
            ? new MultiChannelNotifier({ slackWebhookUrl: env.SLACK_WEBHOOK_URL })
            : null;

          const allOems = ['kia-au','nissan-au','ford-au','volkswagen-au','mitsubishi-au','ldv-au','isuzu-au','mazda-au','kgm-au','gwm-au','suzuki-au','hyundai-au','toyota-au','subaru-au','gmsv-au','foton-au','gac-au','chery-au','renault-au'];
          let driftCount = 0;
          const errors: string[] = [];

          for (const oemId of allOems) {
            try {
              const { data: oem } = await supabase.from('oems').select('base_url').eq('id', oemId).single();
              const url = oem?.base_url || `https://www.${oemId.replace('-au', '')}.com.au`;
              const crawled = await crawler.crawlTokens(url, oemId);

              const { data: tokenRow } = await supabase.from('brand_tokens').select('tokens_json').eq('oem_id', oemId).eq('is_active', true).order('created_at', { ascending: false }).limit(1).single();
              const existing = tokenRow?.tokens_json ?? {};

              // Quick diff on key fields
              let changes = 0;
              if (String(existing.colors?.primary) !== String(crawled.colors.primary)) changes++;
              if (String(existing.typography?.font_primary) !== String(crawled.typography.font_primary)) changes++;
              if (String(existing.colors?.cta_fill) !== String(crawled.colors.cta_fill)) changes++;
              if (changes > 0) driftCount++;

              console.log(`[DesignDrift] ${oemId}: ${changes} changes`);
            } catch (e) {
              errors.push(`${oemId}: ${e instanceof Error ? e.message : String(e)}`);
            }
          }

          if (driftCount > 0 && notifier) {
            await notifier.send(`🎨 Weekly drift check: ${driftCount} of ${allOems.length} OEMs have design changes`).catch(() => {});
          }

          run.status = 'success';
          run.completedAt = new Date().toISOString();
          run.result = { crawl_type: 'design-drift', oems_checked: allOems.length, oems_with_drift: driftCount, errors };
          await saveRun(bucket, run);
          return;
        }

        // Persist progress after every batch so that if the Worker is killed
        // mid-crawl (subrequest/wall-clock budget), the R2 record shows the
        // last completed phase instead of sticking at "running" forever.
        const result = await orchestrator.runScheduledCrawl(crawlType, {
          onProgress: async (partial) => {
            run.result = {
              crawl_type: trigger?.config.crawl_type ?? 'full',
              phase: partial.phase,
              completed: partial.completed,
              total: partial.total,
              elapsedMs: partial.elapsedMs,
              oemResults: partial.oemResults,
            };
            await saveRun(bucket, run);
          },
        });
        console.log(`[${label}] Processed ${result.jobsProcessed} pages, ${result.pagesChanged} changed`);

        run.status = 'success';
        run.completedAt = new Date().toISOString();
        run.result = {
          crawl_type: trigger?.config.crawl_type ?? 'full',
          jobsProcessed: result.jobsProcessed,
          pagesChanged: result.pagesChanged,
          errors: result.errors,
        };
      } catch (e) {
        console.error(`[Scheduled] ${label} failed:`, e);
        run.status = 'failed';
        run.completedAt = new Date().toISOString();
        run.error = e instanceof Error ? e.message : String(e);
      } finally {
        // Always save the run record — even on Worker kill, partial results are better than "running" forever
        try {
          await saveRun(bucket, run);
        } catch (saveErr) {
          console.error(`[Scheduled] Failed to save run record:`, saveErr);
        }
      }
    })
